/* ===== 客席の4方向対応：横向き（o=1:右向き / o=3:左向き）は「手前向きで作ってから90°回す」 ===== */
function fFlip(N){return N.o?Object.assign({},N,{o:4-N.o}):Object.assign({},N,{f:-N.f})}
function sRot(s,x,y){const ax=s.px+2,ay=s.Y0+3,dx=x-ax,dy=y-ay;return s.o===1?[ax+dy,ay-dx]:[ax-dy,ay+dx]}
function sRotV(t,s){t.forEach(v=>{const z=v[5]||1,q=sRot(s,v[0]+z/2,v[1]+z/2);v[0]=q[0]-z/2;v[1]=q[1]-z/2})}
function glFxS(s,kind,col,ly,zo){return s.o===1?glFx(s.px-1,s.Y0+1,1,0,1,kind,col,ly,zo):s.o===3?glFx(s.px+2,s.Y0+1,1,0,3,kind,col,ly,zo):glFx(s.px,s.Y0,s.f,1,0,kind,col,ly,zo)}
{const _sp=seatPose;seatPose=function(t,s,c){_sp(t,s,c);if(s&&s.o)sRotV(t,s)}}
{const _ab=actBuild;actBuild=function(t,p,md){const n0=t.length,r=_ab(t,p,md),s=p.seat;if(s&&s.o){sRotV(t.slice(n0),s);if(r){r.bx.forEach(b=>{const c=sRot(s,b.x+b.w/2,b.y+b.d/2),w=b.d,d=b.w;b.w=w;b.d=d;b.x=c[0]-w/2;b.y=c[1]-d/2});if(r.sp){const q=sRot(s,r.sp[0],r.sp[1]);r.sp[0]=q[0];r.sp[1]=q[1]}}}return r}}
{const _hk=hkCenter;hkCenter=function(p){const s=p.seat;if(!s||!s.o)return _hk(p);const fx=s.o===1?1:-1;
 if(p.sh&&s.kind!=="c"){const A=p.sh.a.seat,B=p.sh.b.seat,o={x:(A.px+B.px)/2+2+fx*5.3,y:(A.Y0+B.Y0)/2+3,rot:s.o};if(s.kind==="b"){o.z=3;o.sc=.7}return o}
 const sh=p.sh;p.sh=null;let o;try{o=_hk(p)}finally{p.sh=sh}const q=sRot(s,o.x,o.y);o.x=q[0];o.y=q[1];o.rot=s.o;return o}}
{const _fv=furnVox;furnVox=function(F,ox,oy){if(!F.o)return _fv(F,ox,oy);const tx=ox!==undefined?ox:F.tx,ty=oy!==undefined?oy:F.ty,n=F.k==="b"?3:SDEF[F.k].n,L=6*n,D=F.k==="b"?18:6;
 return _fv(Object.assign({},F,{f:1,o:0}),0,0).map(v=>{const w=v.slice();if(F.o===1){w[0]=tx*6+v[1];w[1]=ty*6+L-1-v[0]}else{w[0]=tx*6+D-1-v[1];w[1]=ty*6+v[0]}return w})}}
